store_uncertainty_type.definition:
pub type StoreUncertainty {
  StoreUncertainty(
    operation_id: String,
    operation_digest: String,
    witness: Option(CleanupWitness),
    error_reason: String,
  )
}

reconciliation_outcome_type.definition:
pub type ReconciliationOutcome {
  ReconciledCommitted(receipt: Receipt)
  ReconciledAbsent(witness: CleanupWitness)
  ReconciledUnknown(reason: String)
  ReconciledConflict(expected_digest: String, found_receipt: Receipt)
}

response_decode_error_type.definition:
pub type ResponseDecodeError {
  ResponseDecodeError(
    raw_response: String,
    decode_error: String,
    cleanup_witness: Option(CleanupWitness),
    operation_id: String,
    operation_digest: String,
  )
}
